import{_ as e,o,c as t,a2 as l}from"./chunks/framework.z3u3TMv0.js";const h=JSON.parse('{"title":"安装 KoboldCPP","description":"安装 KoboldCPP，加载 GGUF，为 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。","frontmatter":{"title":"安装 KoboldCPP","description":"安装 KoboldCPP，加载 GGUF，为 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。","head":[["meta",{"property":"og:title","content":"安装 KoboldCPP · MiniTavern Docs"}],["meta",{"property":"og:description","content":"安装 KoboldCPP，加载 GGUF，为 MiniTavern 提供 OpenAI 兼容 API（角色扮演常用）。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/koboldcpp/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/koboldcpp/install"}]]},"headers":[],"relativePath":"koboldcpp/install.md","filePath":"koboldcpp/install.md","lastUpdated":1786329914000}'),i={name:"koboldcpp/install.md"};function r(n,a,d,s,p,c){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="安装与上手-koboldcpp" tabindex="-1">安装与上手（KoboldCPP） <a class="header-anchor" href="#安装与上手-koboldcpp" aria-label="Permalink to &quot;安装与上手（KoboldCPP）&quot;">​</a></h1><p><a href="https://github.com/LostRuins/koboldcpp" target="_blank" rel="noreferrer">KoboldCPP</a> 基于 llama.cpp，带轻量界面，在角色扮演社区很常见，可开启 <strong>OpenAI 兼容</strong> HTTP API，供 MiniTavern 连接。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>打开 GitHub Releases，按系统下载对应构建（Windows 常有独立 <code>.exe</code>；其它系统按说明编译或使用发布包）。</li><li>首次运行按提示选择后端（CUDA / Metal / Vulkan / CPU 等），以你硬件为准。</li><li>准备一个 <strong>GGUF</strong> 模型文件（见 <a href="/ultra_guides/local/models">推荐模型</a>）。</li></ol><h2 id="加载模型" tabindex="-1">加载模型 <a class="header-anchor" href="#加载模型" aria-label="Permalink to &quot;加载模型&quot;">​</a></h2><ol><li>在 KoboldCPP 中选择模型文件并启动。</li><li>确认能在其自带聊天或 UI 里正常生成，再开对外 API。</li><li>记下你使用的上下文长度、GPU 层数等；先用默认能跑通即可。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./server">开启 API / 局域网</a> → <a href="/ultra_guides/connect-app/minitavern">在 MiniTavern 中配置</a></p>',8)])])}const b=e(i,[["render",r]]);export{h as __pageData,b as default};
